import type { Source } from "./Core";
/**
 * Callbag operator that combines consecutive values from the same source.
 * It's essentially like array `.reduce`, but delivers a new accumulated value
 * for each value from the callbag source. Works on either pullable or
 * listenable sources.
 *
 * Adapted from https://github.com/staltz/callbag-scan
 *
 * Marble diagram:
 *   " a  b   c    |"
 *   {scan((acc, d) => acc + d, "z")}
 *   " za zab zabc |"
 *
 * @param reducer A function that takes the accumulated value and
 *     the next value and returns a new accumulated value.
 * @param seed An initial accumulating value.
 * @returns A callbag operator that combines consecutive values
 *     from the same source and emits for each element in the source.
 *
 * @internal
 */
export declare const scan: <T, E, U>(reducer: (acc: U, d: T) => U, seed: U) => (source: Source<T, E>) => Source<U, E>;
